<script setup lang="ts">
import {computed,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {useRoute} from 'vue-router'
import {command,message,desktop} from '../api'
import {useAuth} from '../stores/auth'
import type {Study} from '../types'
import ProtocolDocument from '../components/ProtocolDocument.vue'
import PageHeading from '../components/PageHeading.vue'
interface Bundle{id:number;name:string;patient_id:number;patientName:string;deleted:boolean;revision:number;origin:string;actor_id:number|null}
interface Issue{studyId:number;message:string}
const printingValidated=ref(false)
function afterPrint(){printingValidated.value=false}
window.addEventListener('afterprint',afterPrint);onBeforeUnmount(()=>window.removeEventListener('afterprint',afterPrint))
const route=useRoute(),auth=useAuth(),bundle=ref<Bundle>(),studies=ref<Study[]>([]),issues=ref<Issue[]>([]),canPrint=ref(false),reviewed=ref(false),error=ref(''),loading=ref(false),busy=ref(false),confirmOpen=ref(false)
const canManage=computed(()=>Boolean(auth.canWrite&&bundle.value&&(auth.admin||bundle.value.actor_id===auth.user?.id)))
const printReady=computed(()=>canPrint.value&&(!issues.value.length||reviewed.value)&&!loading.value&&!error.value)
let request=0
async function load(){const token=++request;loading.value=true;error.value='';reviewed.value=false;printingValidated.value=false;try{const result=await command<{bundle:Bundle;studies:Study[];issues:Issue[];canPrint:boolean}>('bundle_detail',{id:Number(route.params.id)});if(token===request){bundle.value=result.bundle;studies.value=result.studies;issues.value=result.issues;canPrint.value=result.canPrint}}catch(e){if(token===request){error.value=message(e);canPrint.value=false}}finally{if(token===request)loading.value=false}}
watch(()=>route.params.id,()=>{bundle.value=undefined;studies.value=[];load()},{immediate:true})
async function print(){if(!printReady.value||!bundle.value)return;busy.value=true;error.value='';try{if(desktop)await command('validate_bundle_print',{id:bundle.value.id,revision:bundle.value.revision,expected:studies.value.map(s=>[s.id,s.revision])});printingValidated.value=true;await nextTick();window.print()}catch(e){error.value=message(e);reviewed.value=false}finally{busy.value=false}}
async function changeDeleted(){if(!bundle.value)return;busy.value=true;error.value='';try{await command('set_bundle_deleted',{id:bundle.value.id,revision:bundle.value.revision,deleted:!bundle.value.deleted});confirmOpen.value=false;await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><section class="page-content" :class="{'bundle-print-blocked':!printReady||!printingValidated}"><p class="print-blocked-notice">Печать комплекта недоступна. Обновите документ и проверьте состав в программе.</p><RouterLink v-if="bundle" :to="'/patients/'+bundle.patient_id" class="back-link no-print"><UIcon name="i-lucide-arrow-left"/>К карточке пациента</RouterLink><PageHeading :title="bundle?.name||'Объединённый протокол'" :description="bundle?.patientName"><UButton color="neutral" variant="outline" icon="i-lucide-refresh-cw" :disabled="loading||busy" @click="load">Обновить предпросмотр</UButton><UButton v-if="canManage" color="neutral" variant="ghost" :icon="bundle?.deleted?'i-lucide-undo-2':'i-lucide-trash-2'" :disabled="loading||busy||!desktop" @click="confirmOpen=true">{{bundle?.deleted?'Восстановить комплект':'Удалить комплект'}}</UButton><UButton icon="i-lucide-printer" :disabled="!printReady||busy" :loading="busy" @click="print">Печать всех исследований</UButton></PageHeading><UAlert v-if="error" color="error" variant="soft" :description="error" class="mb-5 no-print"/><UAlert v-if="bundle?.deleted" color="warning" title="Комплект удалён" description="Состав и исходные исследования сохранены. Для печати восстановите комплект." class="mb-5 no-print"/><section v-if="issues.length" class="mb-5 no-print"><UAlert color="warning" title="Проверьте состав комплекта" class="mb-3"/><ul class="grid gap-2 mb-4"><li v-for="(issue,index) in issues" :key="index"><RouterLink :to="'/studies/'+issue.studyId" class="patient-name">№ {{issue.studyId}}</RouterLink>: {{issue.message}}</li></ul><UCheckbox v-if="canPrint" v-model="reviewed" label="Текущие документы и состав проверены" :ui="{root:'items-center',container:'h-auto',label:'block'}"/></section><p class="text-slate-600 mb-6 no-print">{{bundle?.origin==='legacy'?'Комплект перенесён из старой программы. ':''}}Исследования остаются отдельными записями. Показаны текущие сохранённые документы в порядке комплекта.</p><div class="bundle-documents"><ProtocolDocument v-for="study in studies" :key="study.id" :study="study"/></div><UModal v-model:open="confirmOpen" :dismissible="!busy" :title="bundle?.deleted?'Восстановить комплект?':'Удалить комплект?'" description="Входящие исследования сохранятся отдельно. Состав комплекта можно восстановить."><template #body><UAlert v-if="error" color="error" :description="error"/></template><template #footer><UButton color="neutral" variant="outline" :disabled="busy" @click="confirmOpen=false">Отмена</UButton><UButton :color="bundle?.deleted?'primary':'error'" :loading="busy" :disabled="busy" @click="changeDeleted">{{bundle?.deleted?'Восстановить':'Удалить'}}</UButton></template></UModal></section></template>
